# CSD_RATIONALE_BEGIN
# Strategy: natural-delimiter decoding with explicit span-state tracking.
# Outside a span, always use unconstrained steps for ordinary reasoning.
# Before final readiness, naturally opened spans are treated as scratch spans;
# after a scratch span closes, continue unconstrained reasoning so later spans
# may appear. Once final readiness is detected, still remain in natural mode:
# continue unconstrained generation until a natural left delimiter appears.
# Inside a span, only take constrained steps under the positive guard
# helpers.IsComplete(generated) or helpers.CanConstrain(generated), but never
# call AppendConstrainedStep when helpers.IsComplete(generated) is already true;
# instead, wait for a natural right delimiter or leave constrained mode by
# breaking if no valid constrained continuation is available. Local checkpoint
# recovery is bounded and used only to repair dead prefixes during an open span.
# CSD_RATIONALE_END
phase = "reasoning"
inside_span = False
closed_spans = 0
final_ready = False
scratch_mode = False
scratch_ready = False
has_checkpoint = False
checkpoint = []
# invariant helpers.lm == lm
# invariant helpers.parser == parser
# invariant lm.ValidTokensIdsLogits()
# invariant 0 <= stepsLeft <= maxSteps
# invariant |generated| + stepsLeft <= maxSteps
# decreases stepsLeft
while stepsLeft > 0:
    if inside_span:
        if helpers.EndsWithRightDelimiter(generated):
            inside_span = False
            closed_spans = closed_spans + 1
            has_checkpoint = False
            if scratch_mode:
                scratch_mode = False
                scratch_ready = True
                phase = "reasoning"
            else:
                phase = "finalized"
                break
        elif helpers.IsComplete(generated):
            phase = "await_right_delimiter"
            break
        elif helpers.CanConstrain(generated):
            if not has_checkpoint:
                checkpoint = helpers.Checkpoint(generated)
                has_checkpoint = True
            generated, stepsLeft = helpers.AppendConstrainedStep([], generated, stepsLeft)
            if helpers.EndsWithRightDelimiter(generated):
                inside_span = False
                closed_spans = closed_spans + 1
                has_checkpoint = False
                if scratch_mode:
                    scratch_mode = False
                    scratch_ready = True
                    phase = "reasoning"
                else:
                    phase = "finalized"
                    break
            else:
                restored = helpers.RestoreIfDead(generated, checkpoint)
                if restored != generated:
                    generated = restored
                    has_checkpoint = False
        else:
            break
    else:
        if not final_ready:
            if scratch_ready and closed_spans > 0:
                if helpers.MinStepsToComplete(generated) <= 2:
                    final_ready = True
                elif helpers.ParserDistanceToComplete(generated) <= 2:
                    final_ready = True
                elif helpers.ValidContinuationCount(generated) <= 1:
                    final_ready = True
                elif stepsLeft <= 4:
                    final_ready = True
            elif closed_spans >= 2:
                final_ready = True
            elif closed_spans > 0 and stepsLeft <= 3:
                final_ready = True
        if final_ready:
            phase = "finalizing"
        else:
            phase = "reasoning"
        generated, stepsLeft = helpers.AppendUnconstrainedStep([], generated, stepsLeft)
        if helpers.EndsWithLeftDelimiter(generated):
            inside_span = True
            has_checkpoint = False
            if final_ready:
                scratch_mode = False
                phase = "final"
            else:
                scratch_mode = True
                scratch_ready = False
                phase = "scratch"
        elif helpers.EndsWithRightDelimiter(generated):
            closed_spans = closed_spans + 1
            if scratch_mode:
                scratch_mode = False
                scratch_ready = True
